package ro.leo.visual;
import java.io.*;import java.util.*;import android.os.SystemClock;
/** Bounded read-only walk; no symlink traversal, no package data inspection. */
final class StorageAudit {
 static final String[] CATEGORIES={"Muzică","Imagini","Video","Documente","APK / arhive","Altele"};
 static final class Result{long[] bytes=new long[6];int files,visited,unreadable;boolean partial;ArrayList<File> large=new ArrayList<File>();}
 static int category(String name){String n=name.toLowerCase(Locale.ROOT);if(n.matches(".*\\.(mp3|flac|aac|m4a|ogg|opus|wav|wma)$"))return 0;if(n.matches(".*\\.(jpg|jpeg|png|webp|gif|bmp)$"))return 1;if(n.matches(".*\\.(mp4|3gp|mkv|webm|avi)$"))return 2;if(n.matches(".*\\.(txt|pdf|json|csv|vcf|ics|docx?)$"))return 3;if(n.matches(".*\\.(apk|zip|gz|tar|7z|rar)$"))return 4;return 5;}
 static Result scan(File root,int limit,long millis)throws IOException{Result out=new Result();File boundary=root.getCanonicalFile();ArrayDeque<File> stack=new ArrayDeque<File>();HashSet<String> seen=new HashSet<String>();stack.push(boundary);long end=SystemClock.elapsedRealtime()+millis;Comparator<File> order=new Comparator<File>(){public int compare(File a,File b){return Long.compare(a.length(),b.length());}};PriorityQueue<File> top=new PriorityQueue<File>(21,order);while(!stack.isEmpty()){if(Thread.currentThread().isInterrupted()||out.visited>=limit||SystemClock.elapsedRealtime()>end){out.partial=true;break;}File f=stack.pop();out.visited++;try{File canonical=f.getCanonicalFile();if(!canonical.equals(f.getAbsoluteFile())||!LeoFileProvider.inside(boundary,canonical)||!seen.add(canonical.getPath()))continue;if(f.isDirectory()){File[] list=f.listFiles();if(list==null){out.unreadable++;continue;}for(File child:list){if(stack.size()+out.visited>=limit){out.partial=true;break;}stack.push(child);}}else if(f.isFile()){long size=f.length();out.bytes[category(f.getName())]+=size;out.files++;if(size>0){top.add(f);if(top.size()>20)top.poll();}}}catch(IOException|SecurityException e){out.unreadable++;}}out.large.addAll(top);Collections.sort(out.large,Collections.reverseOrder(order));return out;}
}
